#!/usr/bin/env python3
"""Generate the launcher's byte constants from the book's executable verifier."""
import argparse
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[2]


def generate():
    spec = runpy.run_path(str(ROOT / "binaryninja/scripts/verify_client_crash_patches.py"))

    def byte_array(data):
        return "new byte[] { " + ", ".join("0x%02X" % b for b in data) + " }"

    lines = [
        "// Generated by generate_patch_data.py; do not edit byte constants here.",
        "namespace DarkAgesCrashLauncher {",
        "    internal static class PatchData {",
        '        internal const string Sha256 = "%s";' % spec["TARGET_SHA256"],
        "        internal const long FileSize = 3112960;",
        "        internal const uint ImageSize = 0x00506000;",
        "        internal static readonly byte[] Stub = " + byte_array(spec["STUB_TEMPLATE"]) + ";",
        "        internal static readonly Patch[] Patches = new Patch[] {",
    ]
    for p in spec["PATCHES"]:
        lines.append('            new Patch("%s", 0x%08X, %s, %d, %s),' % (
            p.id, p.rva, byte_array(bytes.fromhex(p.original)),
            -1 if p.entry is None else p.entry,
            "null" if not p.fixed else byte_array(bytes.fromhex(p.fixed)),
        ))
    lines += ["        };", "        internal static readonly Relocation[] Relocations = new Relocation[] {"]
    for offset, kind, rva in spec["RELOCATIONS"]:
        lines.append("            new Relocation(0x%03X, %s, 0x%08X)," % (
            offset, "true" if kind == "rel32" else "false", rva,
        ))
    return "\n".join(lines + ["        };", "    }", "}", ""])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = Path(__file__).with_name("PatchData.g.cs")
    text = generate()
    if args.check:
        if not path.exists() or path.read_text() != text:
            raise SystemExit("Launcher byte constants are stale; run generate_patch_data.py")
        print("Launcher byte constants match the canonical patch verifier.")
    else:
        path.write_text(text)
        print("Wrote " + path.name)


if __name__ == "__main__":
    main()
